  "criteria": [
    {
      "id": "task",
      "score": 3,
      "reason": "有回答題目，描述週末活動並解釋喜歡的原因（\"weekend is still my favorite time because I can relax\"），但沒有完整發展細節且語氣較口語。"
    },
    {
      "id": "organization",
      "score": 3,
      "reason": "段落分明（早上/下午/晚上），句子順序基本合理，但連接詞和過渡不夠自然，像是分句用法不流暢（例如 \"Afternoon I play...\"）。"
    },
    {
      "id": "vocabulary",
      "score": 2,
      "reason": "詞彙簡單且多處用詞不準確或不自然，例如 \"cook\" 應為過去或現在式變化，\"many thing\" 及 \"hot noisy\" 等。"
    },
    {
      "id": "grammar",
      "score": 2,
      "reason": "有多處文法錯誤（時態、主詞動詞一致、動名詞/不定詞、冠詞和介系詞使用），例如 \"I must doing homework\"。"
    }
  ],
  "issues": [
    {
      "quote": "In weekend I always sleep until 11 oclock.",
      "type": "preposition",
      "why": "英文中常用慣用片語是 'on the weekend' 或 'at the weekend'（美式用 on），缺少定冠詞或介系詞造成不自然。",
      "suggestion": "On weekends, I always sleep until 11 o'clock."
    },
    {
      "quote": "my mother cook very delicious food.",
      "type": "grammar",
      "why": "主詞 'my mother' 為第三人稱單數，動詞應用第三人稱單數形式 'cooks'；另外 'very delicious food' 可更自然為 'delicious food' 或 'a very delicious breakfast'.",
      "suggestion": "My mother cooks very delicious food."
    },
    {
      "quote": "Afternoon I play the mobile game with my friend, we play two or three hour.",
      "type": "sentence",
      "why": "缺少冠詞/介系詞 ('In the afternoon')，句子之間需要連接詞或句點分隔；時間單位應為複數 'hours'，且動詞時態及數量表達不準確。",
      "suggestion": "In the afternoon, I play mobile games with my friend; we play for two or three hours."
    }
  ],
  "more": [
    {
      "quote": "Because I am very tired in school.",
      "type": "sentence",
      "why": "以 because 開頭的片語獨立成句會造成片段句（sentence fragment）。",
      "suggestion": "Because I am very tired from school, I sleep late on weekends."
    },
    {
      "quote": "Sometime we go to the night market and eat many thing, like chicken and bubble tea.",
      "type": "word-choice",
      "why": "'Sometime' 應為複數 'Sometimes'；'many thing' 應為 'many things' 或更自然的 'a lot of food'.",
      "suggestion": "Sometimes we go to the night market and eat many things, like chicken and bubble tea."
    },
    {
      "quote": "I very like night market because it have many people and is very hot noisy.",
      "type": "grammar",
      "why": "'I very like' 不正確，應為 'I really like' 或 'I like ... very much'；'it have' 主詞動詞不一致，應為 'it has'；'hot noisy' 應分開或用 'hot and noisy'.",
      "suggestion": "I really like the night market because it has many people and is very hot and noisy."
    },
    {
      "quote": "Sunday night I must doing homework, it make me unhappy.",
      "type": "verb",
      "why": "'must doing' 是錯誤結構，情態動詞後接原形動詞；'it make me unhappy' 主詞動詞需一致且時態可改為 'makes'.",
      "suggestion": "On Sunday night I must do homework; it makes me unhappy."
    },
    {
      "quote": "But weekend is still my favorite time because I can relax and no need to study.",
      "type": "cohesion",
      "why": "缺少定冠詞 'the weekend'，且 'no need to study' 應改為完整句子 'I don't need to study' 或 'I do not have to study'.",
      "suggestion": "But the weekend is still my favorite time because I can relax and I don't need to study."
    }
  ],
  "strengths": [
    {
      "quote": "I always sleep until 11 oclock.",
      "why": "清楚表達一個個人習慣，句子目的明確，讓讀者了解你的週末作息。"
    },
    {
      "quote": "But weekend is still my favorite time because I can relax",
      "why": "有直接回答為何喜歡週末，呈現個人感受，符合題目要求的原因說明。"
    }
  ],
  "summary": "你已經能用簡單句描述週末的活動並說出喜歡的原因。接下來請注意動詞時態與主詞動詞一致（例如 'my mother cooks'、'must do'），修正介系詞和冠詞（例如 'on weekends'、'the weekend'），並改善連接句子的方式（避免片段句，多用連接詞或標點）。多做這些小修改會讓文章更自然、更流暢。"
}
